import SwiftUI

struct FinanceView: View { @EnvironmentObject var store: AppStore; @State private var showAdd = false; @State private var filter: MoneyFilter = .all; @State private var editing: MoneyEntry?; var visible: [MoneyEntry] { store.money.sorted { $0.date > $1.date }.filter { filter == .all || (filter == .income && $0.isIncome) || (filter == .spending && !$0.isIncome) } }; var body: some View { ScrollView(showsIndicators: false) { VStack(spacing: 18) { ScreenHeader(icon: "wallet.pass.fill", title: "Финансы", subtitle: "Контролируй доходы и траты", trailing: AnyView(Button { showAdd = true } label: { Image(systemName: "plus").font(.title2).padding(15).background(.ultraThinMaterial, in: Circle()) })); GlassCard { VStack(alignment: .leading, spacing: 10) { HStack { VStack(alignment: .leading) { Text("В этом месяце").foregroundStyle(.secondary); Text("\(Int(store.monthlySpending)) \(store.settings.currency)").font(.system(size: 40, weight: .bold, design: .rounded)) }; Spacer(); Text("🐿️").font(.system(size: 68)) }; ProgressView(value: min(store.monthlySpending / 10000, 1)).tint(.orange); HStack { Text("Траты"); Spacer(); Text("Доходы \(Int(store.monthlyIncome)) \(store.settings.currency)").foregroundStyle(.green) }.font(.caption).foregroundStyle(.secondary) } }.padding(.horizontal, 22); HStack { MetricCard(icon: "arrow.down.left", value: "\(Int(store.monthlySpending))", label: "Расходы", color: .orange); MetricCard(icon: "arrow.up.right", value: "\(Int(store.monthlyIncome))", label: "Доходы", color: .green); MetricCard(icon: "number", value: "\(visible.count)", label: "Операций", color: .purple) }.padding(.horizontal, 22); SectionTitle(title: "История", trailing: "\(visible.count) операций"); Picker("", selection: $filter) { ForEach(MoneyFilter.allCases, id: \.self) { Text($0.title).tag($0) } }.pickerStyle(.segmented).padding(.horizontal, 22); LazyVStack(spacing: 10) { ForEach(visible) { entry in Button { editing = entry } label: { MoneyRow(entry: entry, currency: store.settings.currency) }.buttonStyle(.plain).contextMenu { Button(role: .destructive) { delete(entry) } label: { Label("Удалить", systemImage: "trash") } } } }.padding(.horizontal, 22) }.padding(.bottom, 16) }.sheet(isPresented: $showAdd) { MoneyEditor() }.sheet(item: $editing) { MoneyEditor(entry: $0) } }
    func delete(_ entry: MoneyEntry) { store.money.removeAll { $0.id == entry.id } }
}
struct MoneyRow: View { let entry: MoneyEntry; let currency: String; var body: some View { HStack { Text(entry.emoji).font(.title2).frame(width: 46, height: 46).background(.purple.opacity(0.25), in: RoundedRectangle(cornerRadius: 14)); VStack(alignment: .leading) { Text(entry.title).font(.headline); Text("\(entry.date.formatted(.dateTime.day().month(.abbreviated))) · \(entry.isIncome ? "Доход" : "Трата")").font(.caption).foregroundStyle(.secondary) }; Spacer(); Text("\(entry.isIncome ? "+" : "−")\(entry.amount, specifier: "%.0f") \(currency)").font(.headline).foregroundStyle(entry.isIncome ? .green : .primary); Image(systemName: "chevron.right").foregroundStyle(.secondary) }.padding(13).background(.ultraThinMaterial, in: RoundedRectangle(cornerRadius: 19)) }
}
struct MoneyEditor: View { @EnvironmentObject var store: AppStore; @Environment(\.dismiss) var dismiss; var entry: MoneyEntry?; @State private var title = ""; @State private var amount = ""; @State private var emoji = "🛒"; @State private var income = false; @State private var date = Date(); var body: some View { NavigationStack { Form { Section("Операция") { TextField("Название", text: $title); TextField("Сумма", text: $amount).keyboardType(.decimalPad); TextField("Эмодзи", text: $emoji); Toggle("Это доход", isOn: $income); DatePicker("Дата", selection: $date, displayedComponents: .date) }; Section { Text("Эмодзи вводится обычной клавиатурой iPhone — можно выбрать любой символ.").font(.caption).foregroundStyle(.secondary) } }.navigationTitle(entry == nil ? "Новая операция" : "Изменить").onAppear { if let entry { title = entry.title; amount = String(entry.amount); emoji = entry.emoji; income = entry.isIncome; date = entry.date } }.toolbar { ToolbarItem(placement: .cancellationAction) { Button("Отмена") { dismiss() } }; ToolbarItem(placement: .confirmationAction) { Button("Сохранить") { save(); dismiss() }.disabled(title.isEmpty || Double(amount.replacingOccurrences(of: ",", with: ".")) == nil } } } }
    func save() { let value = Double(amount.replacingOccurrences(of: ",", with: ".")) ?? 0; let new = MoneyEntry(title: title, amount: value, date: date, emoji: emoji.isEmpty ? "💸" : emoji, isIncome: income); if let entry, let i = store.money.firstIndex(where: { $0.id == entry.id }) { var updated = new; updated.id = entry.id; store.money[i] = updated } else { store.money.insert(new, at: 0) } }
}
